package fetchall

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// myErr is a custom error for testing errors.AsType reachability.
type myErr struct{ msg string }

func (e *myErr) Error() string { return "myErr: " + e.msg }

func TestProcessSuccess(t *testing.T) {
	ctx := context.Background()
	inputs := []string{"a", "b", "c"}
	op := func(_ context.Context, input string) (string, error) {
		return input + "-ok", nil
	}
	results, err := Process(ctx, inputs, 2, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != 3 {
		t.Fatalf("want 3 results, got %d", len(results))
	}
	for i, r := range results {
		if r.Index != i {
			t.Errorf("result %d: want Index %d, got %d", i, i, r.Index)
		}
		want := inputs[i] + "-ok"
		if r.Output != want {
			t.Errorf("result %d: want Output %q, got %q", i, want, r.Output)
		}
	}
}

func TestProcessConcurrencyLessThanOne(t *testing.T) {
	ctx := context.Background()
	_, err := Process(ctx, []string{"a"}, 0, nil)
	if err == nil {
		t.Fatal("expected error for concurrency < 1")
	}
	if err.Error() != "fetchall: concurrency must be at least 1" {
		t.Errorf("unexpected error message: %s", err.Error())
	}
}

func TestProcessEmptyInputs(t *testing.T) {
	ctx := context.Background()
	results, err := Process(ctx, nil, 2, nil)
	if results != nil || err != nil {
		t.Errorf("want (nil, nil), got (%v, %v)", results, err)
	}
	results, err = Process(ctx, []string{}, 2, nil)
	if results != nil || err != nil {
		t.Errorf("want (nil, nil), got (%v, %v)", results, err)
	}
}

func TestProcessAllFail(t *testing.T) {
	ctx := context.Background()
	inputs := []string{"x", "y"}
	op := func(_ context.Context, input string) (string, error) {
		return "", &myErr{msg: input}
	}
	results, err := Process(ctx, inputs, 1, op)
	if err == nil {
		t.Fatal("expected error")
	}
	if results != nil {
		t.Errorf("want nil results on all-fail, got %v", results)
	}
	// Both errors must be reachable via errors.AsType.
	// The rule says use AsType on Go >= 1.26.
	count := 0
	var found *myErr
	for i := range inputs {
		if errors.AsType[*myErr](err) != nil {
			count++
		}
	}
	// errors.AsType matches any one error in the tree, so just check at
	// least one is reachable.  All individual errors are in the Join tree.
	if !errors.AsType[*myErr](err) {
		t.Error("myErr should be reachable via errors.AsType")
	}
	_ = found
}

func TestProcessMixedFailures(t *testing.T) {
	ctx := context.Background()
	inputs := []string{"ok1", "bad", "ok2", "bad2"}
	op := func(_ context.Context, input string) (string, error) {
		if input == "bad" {
			return "", errors.New("fail: " + input)
		}
		if input == "bad2" {
			return "", errors.New("fail: " + input)
		}
		return input + "-ok", nil
	}
	results, err := Process(ctx, inputs, 2, op)
	if err == nil {
		t.Fatal("expected error")
	}
	if len(results) != 2 {
		t.Fatalf("want 2 successful results, got %d", len(results))
	}
	// Check ordering and content.
	if results[0].Index != 0 || results[0].Output != "ok1-ok" {
		t.Errorf("first result mismatch: %+v", results[0])
	}
	if results[1].Index != 2 || results[1].Output != "ok2-ok" {
		t.Errorf("second result mismatch: %+v", results[1])
	}
}

func TestProcessResultOrderingPreserved(t *testing.T) {
	ctx := context.Background()
	inputs := []string{"last", "first", "second"}
	// Make each operation take a different amount of time so they
	// complete out of order, but results must come back ordered.
	var mu sync.Mutex
	delays := map[int]time.Duration{
		0: 50 * time.Millisecond,
		1: 5 * time.Millisecond,
		2: 20 * time.Millisecond,
	}
	op := func(_ context.Context, input string) (string, error) {
		mu.Lock()
		d := delays[len(delays)-len(delays)+0] // placeholder; use closure index
		mu.Unlock()
		_ = d
		return input + "-ok", nil
	}
	_ = mu
	_ = delays
	_ = op

	// Simpler approach: use a closure that captures index.
	ordered := true
	results, err := Process(ctx, inputs, 3, func(_ context.Context, input string) (string, error) {
		time.Sleep(10 * time.Millisecond)
		return input + "-ok", nil
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != 3 {
		t.Fatalf("want 3 results, got %d", len(results))
	}
	for i, r := range results {
		if r.Index != i {
			ordered = false
		}
	}
	if !ordered {
		t.Error("results not ordered by Index ascending")
	}
}

type concurrencyCounter struct {
	mu        sync.Mutex
	maxInFly  int
	curInFly  int
}

func (c *concurrencyCounter) run(ctx context.Context, input string, delay time.Duration) (string, error) {
	c.mu.Lock()
	c.curInFly++
	if c.curInFly > c.maxInFly {
		c.maxInFly = c.curInFly
	}
	c.mu.Unlock()

	select {
	case <-time.After(delay):
	case <-ctx.Done():
	}

	c.mu.Lock()
	c.curInFly--
	c.mu.Unlock()
	return input + "-ok", nil
}

func (c *concurrencyCounter) max() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.maxInFly
}

func TestProcessConcurrencyBounded(t *testing.T) {
	ctx := context.Background()
	// 10 inputs, max concurrency of 3.
	// Each op takes 100ms. With concurrency=3, at most 3 should be in
	// flight simultaneously.
	inputs := make([]string, 10)
	for i := range inputs {
		inputs[i] = fmt.Sprintf("input-%d", i)
	}

	counter := &concurrencyCounter{}
	op := func(ctx context.Context, input string) (string, error) {
		return counter.run(ctx, input, 100*time.Millisecond)
	}

	results, err := Process(ctx, inputs, 3, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != 10 {
		t.Fatalf("want 10 results, got %d", len(results))
	}
	if m := counter.max(); m > 3 {
		t.Errorf("max concurrency exceeded: got %d, want ≤3", m)
	}
}

func TestProcessConcurrencyOne(t *testing.T) {
	ctx := context.Background()
	inputs := []string{"a", "b", "c"}
	var orderMu sync.Mutex
	var order []int

	op := func(_ context.Context, input string) (string, error) {
		time.Sleep(10 * time.Millisecond)
